style.css:
@-moz-document domain("music.youtube.com") {
/* Animated Gradient Background */
  body, ytmusic-app {
    background: linear-gradient(270deg, #0d0d1a, #1a001a, #00001a, #0d0d1a);
    background-size: 800% 800%;
    animation: gradientBG 20s ease infinite;
    color: #f0f0f0 !important;
    font-family: 'Orbitron', sans-serif !important;
  }

  @keyframes gradientBG {
    0% {background-position:0% 50%;}
    50% {background-position:100% 50%;}
    100% {background-position:0% 50%;}
  }

  /* Navigation Bar & Player Bar */
  ytmusic-nav-bar, ytmusic-player-bar {
    background-color: rgba(13, 13, 26, 0.85) !important;
    border-top: 2px solid #00ffff !important;
  }

  /* Links & Text */
  a, .title, .yt-simple-endpoint {
    color: #00ffff !important;
  }

  /* Video/Section Backgrounds */
  ytmusic-shelf-renderer, ytmusic-section-list-renderer {
    background-color: rgba(17, 17, 41, 0.85) !important;
    border-radius: 12px !important;
    padding: 6px !important;
    margin: 4px 0 !important;
  }

  /* Player Glow */
  ytmusic-player-bar {
    box-shadow: 0 0 25px #00ffff !important;
  }

  /* Buttons */
  button, paper-icon-button, ytmusic-toggle-button-renderer {
    background-color: rgba(13, 13, 26, 0.85) !important;
    color: #00ffff !important;
    border: 1px solid #00ffff !important;
    border-radius: 4px !important;
    transition: all 0.3s ease;
  }

  /* Hover Effects */
  ytmusic-player-bar button:hover,
  ytmusic-shelf-renderer:hover {
    box-shadow: 0 0 20px #ff00ff !important;
    border-color: #ff00ff !important;
    transform: scale(1.05);
  }
}
